CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.assign_bm_manager() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='kalwannegestaodetrafego@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER bm_manager_after_confirmation AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_bm_manager();
ALTER TABLE public.profiles ADD COLUMN verification_rejection_reason text, ADD COLUMN verification_reviewed_at timestamptz, ADD COLUMN verification_reviewed_by uuid;
CREATE FUNCTION public.guard_bm_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NOT public.has_role(auth.uid(),'admin') THEN IF TG_OP='INSERT' THEN IF NEW.verification_status NOT IN ('pendente','PENDENTE_ANALISE') OR NEW.verification_reviewed_by IS NOT NULL OR NEW.verification_reviewed_at IS NOT NULL OR NEW.verification_rejection_reason IS NOT NULL THEN RAISE EXCEPTION 'Admin approval required'; END IF; ELSE IF NEW.verification_status IS DISTINCT FROM OLD.verification_status AND NEW.verification_status NOT IN ('pendente','PENDENTE_ANALISE') THEN RAISE EXCEPTION 'Admin approval required'; END IF; IF NEW.verification_reviewed_by IS DISTINCT FROM OLD.verification_reviewed_by OR NEW.verification_reviewed_at IS DISTINCT FROM OLD.verification_reviewed_at OR NEW.verification_rejection_reason IS DISTINCT FROM OLD.verification_rejection_reason THEN RAISE EXCEPTION 'Admin approval required'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER bm_guard_verification BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_bm_verification();
CREATE POLICY "Admin pending profile review" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin bookings read" ON public.bookings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_id uuid NOT NULL,action text NOT NULL,target_id uuid NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_actions TO authenticated;
GRANT ALL ON public.admin_actions TO service_role;
ALTER TABLE public.admin_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin audit read" ON public.admin_actions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.bm_review_identity(_profile_id uuid,_approve boolean,_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO p FROM public.profiles WHERE id=_profile_id FOR UPDATE; IF NOT FOUND OR p.verification_status<>'PENDENTE_ANALISE' THEN RAISE EXCEPTION 'Request no longer pending'; END IF; IF _approve AND (p.identity_doc_path IS NULL OR p.selfie_path IS NULL) THEN RAISE EXCEPTION 'Both documents required'; END IF; IF NOT _approve AND length(trim(coalesce(_reason,'')))=0 THEN RAISE EXCEPTION 'Rejection reason required'; END IF; UPDATE public.profiles SET verification_status=CASE WHEN _approve THEN 'VERIFICADO' ELSE 'REJEITADO' END,verification_rejection_reason=CASE WHEN _approve THEN NULL ELSE left(trim(_reason),500) END,verification_reviewed_at=now(),verification_reviewed_by=auth.uid() WHERE id=_profile_id; INSERT INTO public.admin_actions(admin_id,action,target_id,reason) VALUES(auth.uid(),CASE WHEN _approve THEN 'approve_identity' ELSE 'reject_identity' END,_profile_id,CASE WHEN _approve THEN NULL ELSE left(trim(_reason),500) END); END $$;
REVOKE ALL ON FUNCTION public.bm_review_identity(uuid,boolean,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.bm_review_identity(uuid,boolean,text) TO authenticated;
CREATE FUNCTION public.bm_admin_escrow(_booking_id uuid,_release boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO b FROM public.bookings WHERE id=_booking_id FOR UPDATE; IF NOT FOUND OR b.payment_status<>'escrow' THEN RAISE EXCEPTION 'Payment no longer held'; END IF; IF _release AND b.professional_id IS NULL THEN RAISE EXCEPTION 'Assigned professional required'; END IF; IF b.amount_cents<0 OR b.fee_cents<0 OR b.fee_cents>b.amount_cents THEN RAISE EXCEPTION 'Invalid amounts'; END IF; UPDATE public.bookings SET payment_status=CASE WHEN _release THEN 'released' ELSE 'refunded' END,status=CASE WHEN _release THEN 'completed' ELSE 'cancelled' END WHERE id=b.id; DELETE FROM public.wallet_entries WHERE booking_id=b.id AND kind='escrow'; IF _release THEN INSERT INTO public.wallet_entries(owner_id,kind,amount_cents,label,booking_id) VALUES(b.professional_id,'earning',b.amount_cents-b.fee_cents,'Liberação administrativa · simulação',b.id),(b.professional_id,'fee',b.fee_cents,'Taxa BM · simulação',b.id); ELSE INSERT INTO public.wallet_entries(owner_id,kind,amount_cents,label,booking_id) VALUES(b.client_id,'refund',b.amount_cents,'Reembolso administrativo · simulação',b.id); END IF; INSERT INTO public.admin_actions(admin_id,action,target_id) VALUES(auth.uid(),CASE WHEN _release THEN 'release_escrow' ELSE 'refund_escrow' END,b.id); END $$;
REVOKE ALL ON FUNCTION public.bm_admin_escrow(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.bm_admin_escrow(uuid,boolean) TO authenticated;